<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { api } from '../services/api.js'
import DeliveryProofCapture from '../components/DeliveryProofCapture.vue'
import PageSkeleton from '../components/PageSkeleton.vue'

const props = defineProps({ initialTab: { type: String, default: 'orders' }, searchQuery: { type: String, default: '' } })
const tab = ref(props.initialTab)
const pageName = computed(() => ({ orders: 'Orders & Dispatch', planning: 'Load Planning', inventory: 'Warehouse', delivery: 'Delivery & ePOD', assistant: 'Copilot Assistant', alerts: 'Activity Log', analytics: 'Analytics & Reports', returns: 'Returns', rules: 'System Rules' }[tab.value] || 'Operations'))
const rules = ref(null)
const rulesError = ref('')
const loading = ref(true)
const error = ref('')
const notice = ref('')
const data = reactive({ orders: [], shipments: [], delivery_tasks: [], delivery_proofs: [], inventory: [], returns: [], carrier_assignments: [], financial_records: [], order_events: [], fleet_vehicles: [], fleet_vehicle_loads: [], fleet_planning_ready: false, integrations_ready: false })
const order = reactive({ reference_number: '', customer_name: '', origin: '', destination: '', priority: 'standard' })
const item = reactive({ sku: '', name: '', quantity: 0, reorder_point: 0, location: '' })
const returnForm = reactive({ order_id: '', reason: '' })
const assignment = reactive({ order_id: '', carrier_name: '', service_level: 'standard', driver_reference: '', quoted_amount: '' })
const integrationRecord = reactive({ source: 'wms', sku: '', name: '', quantity: 0, reorder_point: 0, location: '', external_id: '', record_type: 'invoice', amount: '', currency: 'USD', status: 'open' })
const importFile = ref(null)
const importing = ref(false)
const proofTask = ref(null)
const savingProof = ref(false)
const lowStock = computed(() => data.inventory.filter((entry) => entry.quantity <= entry.reorder_point))
const queryTerm = computed(() => props.searchQuery.trim().toLocaleLowerCase())
const matchesSearch = (entry) => !queryTerm.value || JSON.stringify(entry).toLocaleLowerCase().includes(queryTerm.value)
const visibleLowStock = computed(() => lowStock.value.filter(matchesSearch))
const visibleFinancialRecords = computed(() => data.financial_records.filter(matchesSearch))
const visibleDeliveryTasks = computed(() => data.delivery_tasks.filter(matchesSearch))
const visibleReturns = computed(() => data.returns.filter(matchesSearch))
const activeOrders = computed(() => data.orders.filter((entry) => entry.status !== 'cancelled' && matchesSearch(entry)))
const activeDeliveryOrders = computed(() => data.orders.filter((entry) => !['delivered', 'cancelled', 'complete'].includes((entry.status || '').toLowerCase())))
const cancelledOrders = computed(() => data.orders.filter((entry) => entry.status === 'cancelled'))
const editingOrder = ref(null)
const editOrder = reactive({ customer_name: '', origin: '', destination: '', priority: 'standard' })
const savingOrder = ref(false)
const chatInput = ref('')
const chatLoading = ref(false)
const chatMessages = ref([{ role: 'assistant', content: 'Ask me about your orders, routes, inventory, delays, or what needs attention. I can give advice, but I will not make operational changes from chat.' }])
const vehicleForm = reactive({ vehicle_reference: '', driver_name: '', capacity_kg: '', compartment_count: '', dock_label: '' })
const selectedVehicleId = ref('')
const loadForm = reactive({ shipment_id: '', slot_code: '', weight_kg: '' })
const savingVehicle = ref(false)
const savingLoad = ref(false)
const selectedVehicle = computed(() => data.fleet_vehicles.find((vehicle) => vehicle.id === selectedVehicleId.value) || data.fleet_vehicles[0] || null)
const vehicleLoads = computed(() => data.fleet_vehicle_loads.filter((load) => load.vehicle_id === selectedVehicle.value?.id))
const loadedShipmentIds = computed(() => new Set(data.fleet_vehicle_loads.map((load) => load.shipment_id)))
const availableLoadShipments = computed(() => data.shipments.filter((shipment) => !['delivered', 'cancelled'].includes(String(shipment.status || '').toLowerCase()) && !loadedShipmentIds.value.has(shipment.id)))
const occupiedSlots = computed(() => new Set(vehicleLoads.value.map((load) => load.slot_code)))
const remainingCapacity = computed(() => Math.max(0, Number(selectedVehicle.value?.capacity_kg || 0) - vehicleLoads.value.reduce((total, load) => total + Number(load.weight_kg || 0), 0)))
const loadSlotOptions = computed(() => Array.from({ length: Number(selectedVehicle.value?.compartment_count || 0) }, (_, index) => `A${index + 1}`).filter((slot) => !occupiedSlots.value.has(slot)))
const shipmentById = computed(() => Object.fromEntries(data.shipments.map((shipment) => [shipment.id, shipment])))
const speechSupported = computed(() => 'speechSynthesis' in window)
watch(() => props.initialTab, (nextTab) => { tab.value = nextTab })
async function loadRules() {
  if (rules.value) return
  rulesError.value = ''
  try { rules.value = await api.getOperationsRules() } catch (err) { rulesError.value = err.message }
}
watch(tab, (nextTab) => { if (nextTab === 'rules') loadRules() })

async function refresh() {
  loading.value = true; error.value = ''
  try { Object.assign(data, await api.getOperationsOverview()); if (!selectedVehicleId.value && data.fleet_vehicles.length) selectedVehicleId.value = data.fleet_vehicles[0].id } catch (err) { error.value = err.message } finally { loading.value = false }
}
async function saveVehicle() {
  savingVehicle.value = true; error.value = ''; notice.value = ''
  try {
    const result = await api.createFleetVehicle({ ...vehicleForm, capacity_kg: Number(vehicleForm.capacity_kg), compartment_count: Number(vehicleForm.compartment_count) })
    notice.value = `${result.vehicle.vehicle_reference} added to the fleet.`
    Object.assign(vehicleForm, { vehicle_reference: '', driver_name: '', capacity_kg: '', compartment_count: '', dock_label: '' })
    await refresh(); selectedVehicleId.value = result.vehicle.id
  } catch (err) { error.value = err.message } finally { savingVehicle.value = false }
}
async function saveLoad() {
  if (!selectedVehicle.value) return
  savingLoad.value = true; error.value = ''; notice.value = ''
  try {
    await api.assignShipmentToVehicle(selectedVehicle.value.id, { ...loadForm, weight_kg: Number(loadForm.weight_kg) })
    notice.value = 'Shipment assigned to the vehicle load plan.'
    Object.assign(loadForm, { shipment_id: '', slot_code: '', weight_kg: '' })
    await refresh()
  } catch (err) { error.value = err.message } finally { savingLoad.value = false }
}
async function removeLoad(load) {
  try { await api.removeFleetLoad(load.id); notice.value = 'Shipment removed from the load plan.'; await refresh() } catch (err) { error.value = err.message }
}
async function saveDeliveryProof(proof) {
  if (!proofTask.value) return
  savingProof.value = true; error.value = ''; notice.value = ''
  try {
    await api.recordDeliveryProof({
      task_id: proofTask.value.id,
      shipment_id: proofTask.value.shipment_id,
      recipient_name: proof.recipientName,
      signature_data_url: proof.signatureDataUrl,
      photo_data_url: proof.photoDataUrl,
    })
    proofTask.value = null
    notice.value = 'Proof recorded and delivery marked complete.'
    await refresh()
  } catch (err) { error.value = err.message } finally { savingProof.value = false }
}
async function createOrder() {
  try { const result = await api.createOrder(order); notice.value = result.agent_result.summary; Object.assign(order, { reference_number: '', customer_name: '', origin: '', destination: '', priority: 'standard' }); await refresh() } catch (err) { error.value = err.message }
}
function beginOrderEdit(entry) {
  editingOrder.value = entry.id
  Object.assign(editOrder, { customer_name: entry.customer_name || '', origin: entry.origin || '', destination: entry.destination || '', priority: entry.priority || 'standard' })
}
async function saveOrderEdit() {
  if (!editingOrder.value) return
  savingOrder.value = true; error.value = ''; notice.value = ''
  try { const result = await api.updateOrder(editingOrder.value, editOrder); notice.value = result.message; editingOrder.value = null; await refresh() } catch (err) { error.value = err.message } finally { savingOrder.value = false }
}
async function removeOrder(entry) {
  if (!window.confirm(`Cancel ${entry.reference_number}? This removes it from active dispatch but preserves its audit history.`)) return
  error.value = ''; notice.value = ''
  try { const result = await api.cancelOrder(entry.id); notice.value = result.message; if (editingOrder.value === entry.id) editingOrder.value = null; await refresh() } catch (err) { error.value = err.message }
}
function speak(text) {
  if (!speechSupported.value) { error.value = 'Voice replies are not supported by this browser.'; return }
  window.speechSynthesis.cancel()
  const utterance = new SpeechSynthesisUtterance(text)
  utterance.rate = 1
  window.speechSynthesis.speak(utterance)
}
async function askAssistant() {
  const message = chatInput.value.trim()
  if (!message || chatLoading.value) return
  chatMessages.value.push({ role: 'user', content: message }); chatInput.value = ''; chatLoading.value = true; error.value = ''
  try { const result = await api.askOperationsAssistant(message); chatMessages.value.push({ role: 'assistant', content: result.reply, provider: result.provider }) } catch (err) { error.value = err.message } finally { chatLoading.value = false }
}
function chooseCsv(event) { importFile.value = event.target.files?.[0] || null }
function eventDetails(event) { return event.details ? JSON.stringify(event.details) : 'No additional details.' }
async function importCsv() {
  if (!importFile.value) { error.value = 'Choose a CSV file first.'; return }
  importing.value = true; error.value = ''; notice.value = ''
  try {
    const result = await api.importOrdersCsv(importFile.value)
    notice.value = `${result.imported} order${result.imported === 1 ? '' : 's'} imported and linked to shipments.${result.failed ? ` ${result.failed} row(s) need attention.` : ''}`
    importFile.value = null; await refresh()
  } catch (err) { error.value = err.message } finally { importing.value = false }
}
async function saveInventory() {
  try { const result = await api.upsertInventory(item); notice.value = result.agent_result.summary; Object.assign(item, { sku: '', name: '', quantity: 0, reorder_point: 0, location: '' }); await refresh() } catch (err) { error.value = err.message }
}
async function createReturn() {
  try { const result = await api.createReturn(returnForm); notice.value = result.agent_result.summary; Object.assign(returnForm, { order_id: '', reason: '' }); await refresh() } catch (err) { error.value = err.message }
}
async function createAssignment() {
  try {
    const payload = { ...assignment }
    if (payload.quoted_amount === '') delete payload.quoted_amount
    else payload.quoted_amount = Number(payload.quoted_amount)
    const result = await api.createCarrierAssignment(payload)
    notice.value = result.status === 'pending_approval' ? 'Assignment saved. A quoted carrier cost requires your confirmation before dispatch.' : 'Assignment saved and ready for your confirmation.'
    Object.assign(assignment, { order_id: '', carrier_name: '', service_level: 'standard', driver_reference: '', quoted_amount: '' }); await refresh()
  } catch (err) { error.value = err.message }
}
async function dispatchAssignment(id) {
  try { const result = await api.dispatchCarrierAssignment(id); notice.value = `Carrier assignment dispatched${result.assignment?.external_assignment_id ? ` (${result.assignment.external_assignment_id})` : ''}.`; await refresh() } catch (err) { error.value = err.message; await refresh() }
}
async function importIntegrationRecord() {
  try {
    const resource = integrationRecord.source === 'wms' ? 'inventory' : 'financial_records'
    const record = resource === 'inventory' ? { sku: integrationRecord.sku, name: integrationRecord.name, quantity: integrationRecord.quantity, reorder_point: integrationRecord.reorder_point, location: integrationRecord.location } : { external_id: integrationRecord.external_id, record_type: integrationRecord.record_type, amount: integrationRecord.amount === '' ? null : Number(integrationRecord.amount), currency: integrationRecord.currency, status: integrationRecord.status }
    const result = await api.syncIntegrationRecords({ integration: integrationRecord.source, resource, records: [record] })
    notice.value = `${result.imported} ${resource === 'inventory' ? 'inventory record' : 'financial record'} imported from ${integrationRecord.source.toUpperCase()}.`; await refresh()
  } catch (err) { error.value = err.message }
}
onMounted(() => { refresh(); if (tab.value === 'rules') loadRules() })
</script>

<template>
  <div>
    <div v-if="error" class="banner error">{{ error }}</div><div v-if="notice" class="banner success">{{ notice }}</div>
    <header class="page-heading"><div><h2>{{ pageName }}</h2><p v-if="tab==='orders'">Create and manage orders, then prepare carrier dispatch.</p><p v-else-if="tab==='planning'">Build vehicle loads from active shipments and available capacity.</p><p v-else-if="tab==='inventory'">Manage warehouse stock and connected ERP or WMS records.</p><p v-else-if="tab==='delivery'">Follow delivery runs and record proof of delivery.</p><p v-else-if="tab==='assistant'">Ask about current shipments, routes, inventory, and delivery work.</p><p v-else-if="tab==='rules'">Review approval thresholds and automated actions.</p><p v-else-if="tab==='returns'">Review and create return workflows.</p><p v-else-if="tab==='analytics'">View current operational totals.</p><p v-else>Review recorded order and dispatch changes.</p></div><button @click="refresh">Refresh</button></header>
    <PageSkeleton v-if="loading" :variant="tab" />
    <template v-else>
      <section v-if="tab==='orders'" class="grid"><form class="panel form" @submit.prevent="createOrder"><h3>Create order → shipment → dispatch</h3><input v-model="order.reference_number" required placeholder="Order reference"/><input v-model="order.customer_name" placeholder="Customer"/><input v-model="order.origin" placeholder="Pickup / origin"/><input v-model="order.destination" placeholder="Delivery destination"/><select v-model="order.priority"><option>standard</option><option>urgent</option></select><button class="primary">Create & dispatch</button><small class="dim">A linked planned shipment is created immediately for the Control Tower.</small></form><form class="panel form" @submit.prevent="importCsv"><h3>Bulk import orders from CSV</h3><input type="file" accept=".csv,text/csv" aria-label="Order CSV file" @change="chooseCsv"/><small class="dim">Required: <strong>reference_number</strong>. Optional: customer_name, origin, destination, priority.</small><button class="primary" :disabled="importing || !importFile">{{ importing ? 'Importing…' : 'Import CSV & create shipments' }}</button></form><form class="panel form" @submit.prevent="createAssignment"><h3>Carrier booking / delivery assignment</h3><select v-model="assignment.order_id" required><option value="" disabled>Select order</option><option v-for="entry in activeOrders" :key="entry.id" :value="entry.id">{{ entry.reference_number }}</option></select><input v-model="assignment.carrier_name" required placeholder="Carrier name"/><input v-model="assignment.service_level" placeholder="Service level"/><input v-model="assignment.driver_reference" placeholder="Driver or vehicle reference"/><input v-model="assignment.quoted_amount" type="number" min="0" step=".01" placeholder="Quoted cost (optional)"/><button class="primary">Prepare assignment</button><small class="dim">Dispatch calls your configured carrier connection only after you confirm it.</small></form><div class="panel list span-all"><h3>Active order management</h3><p class="dim">Changes update the linked shipment and route. Cancelling removes an order from active dispatch while retaining its audit history.</p><article v-for="entry in activeOrders" :key="entry.id"><strong>{{ entry.reference_number }} · {{ entry.customer_name || 'Customer pending' }}</strong><span>{{ entry.status }}</span><p>{{ entry.origin || 'Origin pending' }} → {{ entry.destination || 'Destination pending' }} · {{ entry.priority }}</p><div v-if="editingOrder===entry.id" class="order-edit"><input v-model="editOrder.customer_name" placeholder="Customer"/><input v-model="editOrder.origin" placeholder="Origin"/><input v-model="editOrder.destination" placeholder="Destination"/><select v-model="editOrder.priority"><option>standard</option><option>urgent</option></select><button class="primary" :disabled="savingOrder" @click="saveOrderEdit">{{ savingOrder ? 'Saving…' : 'Save changes' }}</button><button @click="editingOrder=null">Cancel edit</button></div><div v-else class="row-actions"><button @click="beginOrderEdit(entry)">Edit</button><button class="danger-button" @click="removeOrder(entry)">Remove / cancel</button></div></article><p v-if="!activeOrders.length" class="dim">No active orders match this search.</p><details v-if="cancelledOrders.length" class="cancelled-history"><summary>{{ cancelledOrders.length }} cancelled order{{ cancelledOrders.length === 1 ? '' : 's' }} retained in audit history</summary><p v-for="entry in cancelledOrders" :key="entry.id">{{ entry.reference_number }} · {{ entry.customer_name || 'Customer pending' }}</p></details></div><div class="panel list span-all"><h3>Carrier assignments</h3><p v-if="!data.carrier_assignments.length" class="dim">No carrier assignments. Apply migration 007 to enable this integration.</p><article v-for="entry in data.carrier_assignments" :key="entry.id"><strong>{{ entry.carrier_name }} · {{ entry.service_level || 'standard' }}</strong><span>{{ entry.status }}</span><p>{{ entry.driver_reference || 'Driver pending' }} · {{ entry.external_assignment_id || 'Not sent to carrier' }}</p><button v-if="entry.status==='ready_to_dispatch'||entry.status==='pending_approval'" @click="dispatchAssignment(entry.id)">Confirm & dispatch</button></article></div></section>
      <section v-else-if="tab==='planning'" class="load-planning">
        <header class="planning-header panel"><div><span class="mono dim">OPERATIONS / FLEET</span><h2>Load Planning &amp; Capacity</h2><p>Assign active shipments to registered vehicles and keep each load within its recorded weight limit.</p></div><div class="capacity-summary" v-if="selectedVehicle"><div><small>Vehicle capacity</small><strong>{{ Number(selectedVehicle.capacity_kg).toLocaleString() }} kg</strong></div><div><small>Loaded</small><strong>{{ (Number(selectedVehicle.capacity_kg) - remainingCapacity).toLocaleString() }} kg</strong></div><div><small>Slots used</small><strong>{{ vehicleLoads.length }} / {{ selectedVehicle.compartment_count }}</strong></div></div></header>
        <p v-if="!data.fleet_planning_ready" class="banner">Apply migration <code>014_fleet_load_planning.sql</code> to enable saved fleet capacity and cargo assignments.</p>
        <form class="panel vehicle-form" @submit.prevent="saveVehicle"><h3>Register vehicle</h3><input v-model="vehicleForm.vehicle_reference" required maxlength="80" placeholder="Vehicle ID / registration"/><input v-model="vehicleForm.driver_name" placeholder="Driver name (optional)"/><input v-model="vehicleForm.capacity_kg" required type="number" min="1" step="1" placeholder="Capacity in kg"/><input v-model.number="vehicleForm.compartment_count" required type="number" min="1" max="60" placeholder="Cargo slots"/><input v-model="vehicleForm.dock_label" placeholder="Dock (optional)"/><button class="primary" :disabled="savingVehicle || !data.fleet_planning_ready">{{ savingVehicle ? 'Saving…' : 'Add vehicle' }}</button></form>
        <div v-if="data.fleet_vehicles.length" class="vehicle-select"><label for="load-vehicle">Planning vehicle</label><select id="load-vehicle" v-model="selectedVehicleId"><option v-for="vehicle in data.fleet_vehicles" :key="vehicle.id" :value="vehicle.id">{{ vehicle.vehicle_reference }} · {{ Number(vehicle.capacity_kg).toLocaleString() }} kg · {{ vehicle.status }}</option></select></div>
        <div v-if="selectedVehicle" class="planning-grid"><section class="panel cargo-panel"><header><div><h3>Cargo compartments · {{ selectedVehicle.vehicle_reference }}</h3><p>{{ selectedVehicle.driver_name || 'Driver not assigned' }} <span v-if="selectedVehicle.dock_label">· {{ selectedVehicle.dock_label }}</span></p></div><span class="vehicle-status">{{ selectedVehicle.status }}</span></header><div class="compartment-grid"><article v-for="n in Number(selectedVehicle.compartment_count)" :key="n" class="compartment" :class="{ occupied: vehicleLoads.some((load) => load.slot_code === `A${n}`) }"><span>A{{ n }}</span><template v-if="vehicleLoads.find((load) => load.slot_code === `A${n}`)"><strong>{{ shipmentById[vehicleLoads.find((load) => load.slot_code === `A${n}`).shipment_id]?.reference_number || 'Shipment' }}</strong><small>{{ Number(vehicleLoads.find((load) => load.slot_code === `A${n}`).weight_kg).toLocaleString() }} kg</small><button aria-label="Remove shipment from compartment" @click="removeLoad(vehicleLoads.find((load) => load.slot_code === `A${n}`))">×</button></template><span v-else class="slot-empty">Empty</span></article></div><div class="capacity-meter"><span>Remaining capacity</span><strong>{{ remainingCapacity.toLocaleString() }} kg</strong><i><b :style="{ width: `${selectedVehicle.capacity_kg ? 100 * (selectedVehicle.capacity_kg - remainingCapacity) / selectedVehicle.capacity_kg : 0}%` }"></b></i></div></section>
          <aside class="panel load-assignment"><h3>Assign shipment</h3><p class="dim">Only active shipments not already loaded are available.</p><form @submit.prevent="saveLoad"><label>Shipment<select v-model="loadForm.shipment_id" required><option value="" disabled>Select shipment</option><option v-for="shipment in availableLoadShipments" :key="shipment.id" :value="shipment.id">{{ shipment.reference_number }} · {{ shipment.origin || 'Origin pending' }} → {{ shipment.destination || 'Destination pending' }}</option></select></label><label>Compartment<select v-model="loadForm.slot_code" required><option value="" disabled>Select available slot</option><option v-for="slot in loadSlotOptions" :key="slot" :value="slot">{{ slot }}</option></select></label><label>Cargo weight (kg)<input v-model="loadForm.weight_kg" type="number" min="1" :max="remainingCapacity" step=".1" required/></label><button class="primary" :disabled="savingLoad || !loadForm.shipment_id || !loadForm.slot_code || Number(loadForm.weight_kg) > remainingCapacity">{{ savingLoad ? 'Saving…' : 'Assign to vehicle' }}</button></form><p v-if="!availableLoadShipments.length" class="load-empty">No unassigned active shipments are available.</p></aside>
        </div><section v-else class="panel no-vehicles"><h3>No fleet vehicles registered</h3><p>Enter a vehicle’s actual capacity and cargo slot count above to start a load plan.</p></section>
      </section>
      <section v-else-if="tab==='rules'" class="rules-page"><header class="panel"><span class="mono dim">CONTROL POLICY</span><h2>System Rules</h2><p>Current deterministic thresholds and approval gates used by shipment risk and operations workflows.</p></header><p v-if="rulesError" class="banner error">{{ rulesError }}</p><PageSkeleton v-else-if="!rules" variant="list" /><template v-else><div class="panel rules-panel"><h3>Delay risk thresholds</h3><p>Severity is assigned from the current delay against the original ETA.</p><article v-for="(hours, severity) in rules.delay_thresholds_hours" :key="severity"><span class="rule-severity" :class="severity">{{ severity }}</span><strong>{{ hours }} hours or more</strong></article></div><div class="panel rules-panel"><h3>Approval policy</h3><p>Actions follow the same policy used by the operations approval service.</p><ul><li v-for="rule in rules.action_policy.human_approval" :key="rule">{{ rule }}</li></ul><h4>Actions that can run autonomously</h4><div class="rule-chips"><span v-for="action in rules.action_policy.autonomous_actions" :key="action">{{ action.replaceAll('_',' ').toLowerCase() }}</span></div><p class="dim">Unknown actions: {{ rules.action_policy.unknown_action }}</p></div></template></section>
      <section v-else-if="tab==='inventory'" class="grid"><form class="panel form" @submit.prevent="saveInventory"><h3>Inventory / warehouse update</h3><input v-model="item.sku" required placeholder="SKU"/><input v-model="item.name" required placeholder="Item name"/><input v-model.number="item.quantity" type="number" placeholder="Quantity"/><input v-model.number="item.reorder_point" type="number" placeholder="Reorder point"/><input v-model="item.location" placeholder="Shelf / warehouse location"/><button class="primary">Save & evaluate stock</button></form><form class="panel form" @submit.prevent="importIntegrationRecord"><h3>ERP / WMS record import</h3><select v-model="integrationRecord.source"><option value="wms">WMS inventory</option><option value="erp">ERP financial record</option></select><template v-if="integrationRecord.source==='wms'"><input v-model="integrationRecord.sku" required placeholder="External SKU"/><input v-model="integrationRecord.name" required placeholder="Item name"/><input v-model.number="integrationRecord.quantity" type="number" placeholder="Quantity"/><input v-model.number="integrationRecord.reorder_point" type="number" placeholder="Reorder point"/><input v-model="integrationRecord.location" placeholder="Warehouse location"/></template><template v-else><input v-model="integrationRecord.external_id" required placeholder="ERP external record ID"/><input v-model="integrationRecord.record_type" required placeholder="Invoice, bill, credit…"/><input v-model="integrationRecord.amount" type="number" step=".01" placeholder="Amount"/><input v-model="integrationRecord.currency" placeholder="Currency"/><input v-model="integrationRecord.status" placeholder="Record status"/></template><button class="primary">Import source record</button><small class="dim">Financial imports record facts; they cannot create payments or spend.</small></form><div class="panel list span-all"><h3>Inventory exceptions & financial records</h3><p v-if="!visibleLowStock.length && !visibleFinancialRecords.length" class="dim">No stock or financial exceptions.</p><article v-for="entry in visibleLowStock" :key="entry.id"><strong>{{ entry.sku }} · {{ entry.name }}</strong><span class="danger">replenishment review</span><p>{{ entry.quantity }} on hand · reorder point {{ entry.reorder_point }}</p></article><article v-for="entry in visibleFinancialRecords" :key="entry.id"><strong>{{ entry.record_type }} · {{ entry.document_number || entry.external_id }}</strong><span>{{ entry.status || 'recorded' }}</span><p>{{ entry.amount ?? '—' }} {{ entry.currency }}</p></article></div></section>
      <section v-else-if="tab==='delivery'" class="delivery-view">
        <div class="delivery-summary"><article class="panel"><span>Assigned deliveries</span><strong>{{ data.delivery_tasks.length }}</strong></article><article class="panel"><span>Orders in progress</span><strong>{{ activeDeliveryOrders.length }}</strong></article><article class="panel"><span>Carrier bookings</span><strong>{{ data.carrier_assignments.length }}</strong></article></div>
        <div class="panel full"><div class="delivery-heading"><div><h3>Delivery runs</h3><p>Review the driver, destination, and current delivery status. Route events and customer proof are shown when a connected carrier provides them.</p></div><button @click="refresh">Refresh</button></div>
          <div v-if="!data.delivery_tasks.length" class="delivery-empty"><strong>No delivery runs yet</strong><span>Create an order or import dispatch work to see assigned deliveries here.</span><button class="primary" @click="tab='orders'">Go to orders & dispatch</button></div>
